/*
 * A071032  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 86".
 * https://oeis.org/A071032
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 8870, u16 n <= 8870, u32 n <= 8870, u64 n <= 8870,
 *            u128 n <= 8870, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Computes A071032 (triangle read by rows of Rule 86 cellular
 *  automaton).  The function builds rows on demand and returns the
 *  bit at position n when the triangle is flattened row‑wise.  The
 *  values are stored as seq_t; the implementation works for both
 *  integral and arbitrary‑precision seq_t types.  */

#include <stdlib.h>

/* Integer floor square root:   sqrt_floor(n) = ⌊√n⌋ */
static idx_t int_sqrt(idx_t x)
{
    idx_t res = 0;
    idx_t bit = 1ULL << 62;                 /* highest power of four ≤ x */
    while (bit > x) bit >>= 2;
    while (bit) {
        if (x >= res + bit) {
            x -= res + bit;
            res = (res >> 1) + bit;
        } else {
            res >>= 1;
        }
        bit >>= 2;
    }
    return res;
}

/* Rule 86 truth table (values 0 or 1).  Index is (left<<2)|(center<<1)|right. */
static const seq_t rule86[8] = {
    (seq_t)0, /* 000 */
    (seq_t)1, /* 001 */
    (seq_t)1, /* 010 */
    (seq_t)0, /* 011 */
    (seq_t)1, /* 100 */
    (seq_t)0, /* 101 */
    (seq_t)1, /* 110 */
    (seq_t)0  /* 111 */
};

/* Cached list of row pointers. */
static seq_t **rows = NULL;      /* array of pointers to rows */
static size_t rows_len = 0;      /* number of rows stored  */
static size_t rows_cap = 0;      /* capacity of rows array */

/* Ensure rows 0 … target_row are generated. */
static void ensure_rows(idx_t target_row)
{
    while (rows_len <= target_row) {
        size_t r = rows_len;                      /* index of new row */
        size_t len = 2 * r + 1;                   /* length of new row */
        seq_t *row = (seq_t*)malloc(len * sizeof(seq_t));
        if (!row) abort();                        /* OOM */

        if (r == 0) {          /* first row */
            row[0] = (seq_t)1;
        } else {
            seq_t *prev = rows[r - 1];
            size_t prev_len = 2 * (r - 1) + 1;

            for (size_t i = 0; i < len; ++i) {
                seq_t left   = (i >= 2)              ? prev[i - 2] : (seq_t)0;
                seq_t center = (i >= 1 && i - 1 < prev_len) ? prev[i - 1] : (seq_t)0;
                seq_t right  = (i < prev_len)        ? prev[i] : (seq_t)0;

                unsigned int mask =
                    ((left  != (seq_t)0) << 2) |
                    ((center!= (seq_t)0) << 1) |
                    (right != (seq_t)0);

                row[i] = rule86[mask];
            }
        }

        /* Grow the row pointer table if needed. */
        if (rows_len == rows_cap) {
            size_t new_cap = (rows_cap == 0) ? 4 : rows_cap * 2;
            seq_t **tmp = (seq_t**)realloc(rows, new_cap * sizeof(seq_t*));
            if (!tmp) abort();                /* OOM */
            rows = tmp;
            rows_cap = new_cap;
        }
        rows[rows_len++] = row;
    }
}

/* Public function requested.  Returns the n‑th term of A071032. */
seq_t a(idx_t n)
{
    /* Compute row and column from the flattened index n. */
    idx_t row = int_sqrt(n);
    idx_t col = n - row * row;          /* 0 ≤ col ≤ 2*row */

    /* Generate rows up to the required one. */
    ensure_rows(row);

    /* Return the value. */
    return rows[row][col];
}
